#include <FFPMscTtilde.hpp>
#include <cmath>
#include <complex>
#include <mxpart_mod.hpp>
#include <sprods_com_mod.hpp>
#include <FArray.hpp>

using namespace mxpart_mod;
using namespace sprods_com_mod;

// Z. Bern, L. Dixon, D.A. Kosower, e-Print:hep-ph/9708239
// Eq.10.22
std::complex<double> FFPMscTtilde(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  double deltat14, deltat56, Deltat3;

  auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) {
      return za(i1,i2)*zb(i2,i4) + za(i1,i3)*zb(i3,i4);
  };
  auto zab = [&za, &zb](int i1, int i2, int i3) {
      return za(i1,i2)*zb(i2,i3);
  };

  deltat14 = s(j1,j4) - s(j2,j3) - s(j5,j6);
  deltat56 = s(j5,j6) - s(j1,j4) - s(j2,j3);
  Deltat3 = std::pow(s(j1,j4),2) + std::pow(s(j2,j3),2) + std::pow(s(j5,j6),2)
      - 2*s(j1,j4)*s(j2,j3) - 2*s(j2,j3)*s(j5,j6) - 2*s(j5,j6)*s(j1,j4);

  std::complex<double> res =
      3*za(j1,j4)*zb(j2,j3)*zab2(j2,j3,j4,j1)
      /(zab2(j3,j1,j2,j4)*std::pow(Deltat3,2))
      *((deltat14*zab(j2,j5,j6)-s(j5,j6)*zab(j2,j3,j6))*zab(j5,j4,j1)
      -0.5*deltat56*zab(j2,j5,j6)*zab(j5,j6,j1))

      -zab2(j2,j3,j4,j1)/(zab2(j3,j1,j2,j4)*Deltat3)
      *(0.5*zab(j4,j5,j6)*(zab(j5,j6,j3)+2*zab(j5,j2,j3))
      -zab(j5,j2,j3)*zab(j4,j1,j6));

  // @coverage-probe
  return res;
}

extern "C" {
  std::complex<double> FFPMscTtilde_wrapper(int j1, int j2, int j3, int j4, int j5, int j6, std::complex<double>* fza, std::complex<double>* fzb) {
    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
    return FFPMscTtilde(j1, j2, j3, j4, j5, j6, za, zb);
  }
}
